import {mountRepairExamHistory} from './workshop-repair-exam-history-ui.mjs';
import {retryRepairCase,repairExamTotal} from './workshop-repair-exam-history.mjs';
import {newRepairExam,examIntervene,examMeasure,repairExamGrade,submitRepairCase,validRepairExam,saveRepairExam,repairExamKey} from './workshop-repair-exam-model.mjs';
import {repairState,newRepair,intervene,causes} from './workshop-repair-model.mjs';
import {required,snapshot} from './workshop-model.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
import {mountWorkshopBench} from './workshop-bench.mjs';
import {initialLanguage} from './i18n.mjs';
const $=s=>document.querySelector(s),add=(tag,text,host)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};let lang=initialLanguage(),exam=null,time=.5,playing=false,cut=true,last=0,error=false,replayStep=null;const views=new Map();try{const data=JSON.parse(localStorage.getItem(repairExamKey)||'null');if(validRepairExam(data))exam=data;}catch{error=true;}
const t=(es,en)=>lang==='es'?es:en,local=x=>x[lang],fix=(r,id)=>local(id==='primary'?caseInfo[r.kind].fix:alternate[r.kind].fix);
const historyUI=mountRepairExamHistory({language:()=>lang,busy:()=>Boolean(exam&&!exam.finished),review:(original,index)=>{exam=structuredClone(original);exam.index=index;replayStep=0;time=.5;playing=false;save();render();$('#exam').scrollIntoView();},retry:(original,index)=>{const next=retryRepairCase(original,index);if(!next)return;exam=next;replayStep=null;time=.5;playing=false;save();render();$('#exam').scrollIntoView();},cancel:()=>{exam=null;playing=false;try{localStorage.removeItem(repairExamKey);}catch{error=true;}render();}});
function save(){try{saveRepairExam(localStorage,exam);error=false;}catch{error=true;}}
function currentRepair(){const r=exam.cases[exam.index].repair;if(!exam.finished||replayStep===null)return r;const copy=newRepair(r);for(const a of r.actions.slice(0,replayStep))intervene(copy,a.id);return copy;}
function bench(kind){if(!views.has(kind)){const node=add('div','',$('#banks'));node.className='case-banks';const hosts=[0,1].map(i=>{const card=add('article','',node);add('h3',i?'B':'A',card);const h=add('div','',card);h.className='workshop-viewport';return h;});const a=mountWorkshopBench(hosts[0],kind,'A'),b=mountWorkshopBench(hosts[1],kind,'B');if(a&&b){a.onView(v=>b.setView(v));b.onView(v=>a.setView(v));}else hosts.forEach(h=>{if(!h.querySelector('canvas'))h.textContent=t('3D no disponible; usa las mediciones.','3D unavailable; use measurements.');});views.set(kind,{node,a,b});}for(const [k,v]of views)v.node.hidden=k!==kind;const v=views.get(kind);v.a?.setCut(cut);v.b?.setCut(cut);return v;}
function reading(m,id){return ({battery:m.loaded+' V',ground:m.drop+' V',input:'Vin '+m.inputPeak+' V · G '+m.gain,output:'Vout '+m.outputPeak+' V · ±'+m.rail+' V',speed:m.speed+' mm/s',flow:m.inlet+' L/min',leak:m.leak+' L/min',supply:m.supply+' bar',exhaust:m.back+' bar'})[id];}
function draw(){if(!exam)return;const r=currentRepair(),v=bench(r.kind),s=repairState(r);v.a?.draw(snapshot({...s,time},true),time);v.b?.draw(snapshot({...s,time}),time);$('#clock').value=Math.round(time*100);$('#clockValue').textContent='t = '+time.toFixed(2)+' · A '+t('sano','healthy')+' / B '+t('caso','case');$('#play').textContent=playing?t('Pausar','Pause'):t('Reproducir a 0,5×','Play at 0.5×');}
function render(){historyUI.render();$('#historyJump').textContent=t('Ver historial de exámenes','View exam history');document.documentElement.lang=lang;$('#language').value=lang;$('#languageLabel').textContent=t('Idioma','Language');$('#back').textContent=t('← Resumen y plan de reparación','← Repair summary and plan');$('#back').href='workshop-exam.html?lang='+lang+'#repairWeekly';$('#title').textContent=t('Examen semanal de reparación','Weekly repair exam');$('#intro').textContent=t('Cuatro casos sorpresa: mecánica, electrónica, hidráulica y neumática. Sin pistas, notas ni correcciones hasta terminar los cuatro. Mide, intervén y repite las pruebas. Se restan 40 puntos por causa pendiente, 15 por intervención innecesaria y 20 si faltan pruebas posteriores en 0,5 y 1,25. La respuesta del equipo siempre es visible.','Four surprise cases: mechanics, electronics, hydraulics and pneumatics. No hints, grades or corrections until all four are finished. Measure, intervene and repeat tests. Lose 40 points per remaining cause, 15 per unnecessary intervention and 20 for missing post-intervention tests at 0.5 and 1.25. Equipment response is always visible.');$('#save').textContent=error?t('No se pudo guardar. Sigue en memoria; reintenta guardar.','Could not save. Still in memory; retry saving.'):t('Progreso guardado en este navegador.','Progress saved in this browser.');if(error&&exam){const b=add('button',t('Reintentar guardar','Retry saving'),$('#save'));b.onclick=()=>{save();render();};}$('#start').textContent=exam&&!exam.finished?t('Abandonar e iniciar otro','Abandon and start another'):t('Iniciar examen sorpresa','Start surprise exam');$('#exam').hidden=!exam;$('#results').replaceChildren();if(!exam)return;if(exam.retryOf){$('#title').textContent=t('Reintento de reparación · un caso','Repair retry · one case');$('#intro').textContent=t('Misma avería del examen original, sin pistas hasta enviar. El resultado se guarda por separado; la nota original no cambia.','Same fault as the original exam, with no hints until submission. Your result is saved separately; the original grade stays unchanged.');}const c=exam.cases[exam.index],r=currentRepair();$('#caseTitle').textContent=(exam.retryOf?'1/1':(exam.index+1)+'/4')+' · '+local(caseInfo[r.kind].title);$('#instruction').textContent=exam.finished?t('Revisión: elige un paso para reproducir exactamente tus intervenciones.','Review: choose a step to replay your interventions.'):t('A es la referencia sana. B refleja tus intervenciones; no se indica si fueron necesarias hasta terminar.','A is the healthy reference. B reflects your interventions; their usefulness is not disclosed until the end.');$('#clockLabel').textContent=t('Reloj compartido','Shared clock');$('#cut').textContent=t('Abrir/cerrar corte','Toggle cutaway');$('#limits').textContent=local(caseInfo[r.kind].limit);$('#measurements').replaceChildren();for(const sample of [.5,1.25])for(const id of required[r.kind]){const field=add('fieldset','',$('#measurements'));add('legend',local(caseInfo[r.kind].tests[id])+' · t = '+sample,field);const b=add('button',t('Medir','Measure'),field);b.dataset.measure=id+':'+sample;b.onclick=()=>{time=sample;playing=false;examMeasure(c,id,sample);const part=({battery:'battery',ground:'ground',input:'signals',output:'signals',speed:'piston',flow:'flow',leak:'leak',supply:'regulator',exhaust:'silencer'})[id],v=bench(r.kind);v.a?.select(part);v.b?.select(part);save();render();};if(exam.finished||c.observations.some(o=>o.id===id&&o.time===sample)){const state=repairState(r);add('p','A: '+reading(snapshot({...state,time:sample},true),id)+' · B: '+reading(snapshot({...state,time:sample}),id),field);}}
$('#actions').replaceChildren();for(const id of ['primary','alternate']){const b=add('button',fix(r,id),$('#actions'));b.dataset.fix=id;b.disabled=Boolean(exam.finished);b.onclick=()=>{examIntervene(c,id);time=0;playing=false;save();render();};}add('p',t('Intervenciones registradas: ','Recorded interventions: ')+c.repair.actions.length,$('#actions'));$('#submit').disabled=Boolean(exam.finished);$('#submit').textContent=(exam.retryOf||exam.index===3)?t('Enviar y terminar examen','Submit and finish exam'):t('Enviar caso y continuar','Submit case and continue');
if(exam.finished){const results=$('#results'),grades=exam.cases.map(repairExamGrade);add('h2',t('Resultado: ','Result: ')+repairExamTotal(exam)+'/100',results);add('p',error?t('Guarda los resultados para actualizar el plan.','Save results to update your plan.'):t('Los casos con errores se programan para mañana. El examen no suma a la meta diaria ni a la racha; completa una reparación de práctica para ello.','Cases with mistakes are scheduled for tomorrow. The exam does not count toward daily goals or streaks; complete a practice repair for that.'),results);for(const [i,entry]of exam.cases.entries()){if(exam.retryOf&&i!==exam.retryIndex)continue;const b=add('button',local(caseInfo[entry.repair.kind].title)+' · '+grades[i].score+'/100',results);b.dataset.review=i;b.onclick=()=>{exam.index=i;replayStep=0;time=.5;playing=false;save();render();$('#exam').scrollIntoView();};}const g=grades[exam.index];add('h3',t('Explicación de tus decisiones','Your decisions explained'),results);add('p',g.verified?t('Todas las causas corregidas y las pruebas posteriores completas.','All causes corrected and post-repair tests complete.'):t('La reparación quedó sin verificar. Revisa causas pendientes y pruebas posteriores.','Repair was not verified. Review remaining causes and post-repair tests.'),results);if(!g.evidence)add('p',t('Faltaron pruebas después de la última intervención. Una lectura anterior no comprueba la reparación.','Tests were missing after the last intervention. An earlier reading does not verify the repair.'),results);for(const id of causes(c.repair)){add('p',fix(r,id)+' · '+(g.remaining.includes(id)?t('Pendiente. ','Still needed. '):t('Aplicada. ','Applied. '))+t('Efecto de esta causa por separado: ','Effect of this cause in isolation: ')+local(id==='primary'?caseInfo[r.kind].explain:alternate[r.kind].explain),results);}if(c.repair.fault.startsWith('intermittent-'))add('p',t('La avería aparece entre 0,75 y 1,75 de cada período de 2. Compara 0,5 y 1,25: una lectura normal aislada no la descarta.','The fault appears between 0.75 and 1.75 in each 2-unit period. Compare 0.5 and 1.25: one normal reading does not rule it out.'),results);const before=add('button',t('Antes de reparar','Before repair'),results);before.onclick=()=>{replayStep=0;time=.5;playing=false;render();$('#exam').scrollIntoView();};for(const [i,a]of c.repair.actions.entries()){const b=add('button',(i+1)+'. '+fix(r,a.id)+' · '+(a.useful?t('Causa corregida','Cause corrected'):t('Innecesaria: no eliminó una causa pendiente','Unnecessary: removed no remaining cause')),results);b.dataset.step=i+1;b.onclick=()=>{replayStep=i+1;time=1.25;playing=false;render();$('#exam').scrollIntoView();};}add('p',t('Paso mostrado: ','Displayed step: ')+(replayStep??c.repair.actions.length)+' / '+c.repair.actions.length,results);const hint=add('button',t('Pista para el repaso','Review hint'),results);hint.onclick=()=>{add('p',t('Compara cada magnitud con A, corrige solo la causa respaldada y repite todas las pruebas después de intervenir. En un caso combinado una sola corrección puede no bastar.','Compare each quantity with A, correct only the supported cause and repeat every test afterward. One correction may not be enough for a combined case.'),results);};}
draw();}
$('#start').onclick=()=>{exam=newRepairExam();replayStep=null;time=.5;playing=false;save();render();};$('#submit').onclick=()=>{submitRepairCase(exam);replayStep=null;time=.5;playing=false;save();render();};$('#language').onchange=e=>{lang=e.target.value;const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);render();};$('#clock').oninput=e=>{time=+e.target.value/100;playing=false;draw();};$('#cut').onclick=()=>{cut=!cut;draw();};let frame=0;function tick(now){frame=0;if(!playing||document.hidden)return;time=Math.min(7.99,time+(last?Math.min(.05,(now-last)/1000):0)*.5);last=now;draw();if(time>=7.99)playing=false;if(playing)frame=requestAnimationFrame(tick);}$('#play').onclick=()=>{playing=!playing;if(time>=7.99)time=0;last=0;if(playing&&!frame)frame=requestAnimationFrame(tick);draw();};document.addEventListener('visibilitychange',()=>{if(document.hidden)playing=false;});new IntersectionObserver(([e])=>{if(!e.isIntersecting)playing=false;}).observe($('#banks'));matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',()=>{playing=false;draw();});render();window.repairExamDebug=()=>exam;
